import{_ as o,o as a,c,ai as d}from"./chunks/framework.Ba-VnP44.js";const _=JSON.parse('{"title":"企业资产管理 · OpenBiz 第六个独立消费者","description":"","frontmatter":{},"headers":[],"relativePath":"apps/openbiz/eam.md","filePath":"apps/openbiz/eam.md"}'),i={name:"apps/openbiz/eam.md"};function n(r,e,p,t,E,l){return a(),c("div",null,[...e[0]||(e[0]=[d('<h1 id="企业资产管理-·-openbiz-第六个独立消费者" tabindex="-1">企业资产管理 · OpenBiz 第六个独立消费者 <a class="header-anchor" href="#企业资产管理-·-openbiz-第六个独立消费者" aria-label="Permalink to “企业资产管理 · OpenBiz 第六个独立消费者”">​</a></h1><blockquote><p>现为独立应用 <code>openbiz-eam-app</code>（<code>E:/8.cangku/for-job/openbiz-eam-app</code>）：独立后端（端口 18086）+ 独立前端（Vue3/TS）+ 独立数据库 <code>openbiz_eam</code>。</p></blockquote><blockquote><p>实证：OpenBiz 母仓无 EAM 域，按 OpenBiz 命名约定自建 <code>openbiz_eam_*</code> 表，在其多租户基座之上实现「资产 + 维修单状态机 + 跨实体联动」最小闭环。验证 OpenBiz V0.2「更多独立 consumer」目标。</p></blockquote><h2 id="复用与自建" tabindex="-1">复用与自建 <a class="header-anchor" href="#复用与自建" aria-label="Permalink to “复用与自建”">​</a></h2><ul><li><strong>复用</strong>：OpenBiz <code>openbiz-saas-core</code> 多租户（TenantContext / TenantService / 自动装配）、RuoYi 登录外壳</li><li><strong>自建</strong>：<code>openbiz_eam_asset</code> / <code>openbiz_eam_repair_order</code> 表 + Mapper / Service / Controller <ul><li>资产状态机：<code>IDLE → IN_USE → MAINTENANCE → IN_USE</code>，<code>IDLE/IN_USE → RETIRED</code>（不可逆终态）</li><li>维修单状态机：<code>CREATED → SCHEDULED → REPAIRING → DONE</code>，<code>CREATED/SCHEDULED → CANCELLED</code></li><li><strong>跨实体联动</strong>：维修单进入 <code>REPAIRING</code> 时，Service 层在同一事务内将对应资产置为 <code>MAINTENANCE</code>（外部事件驱动，绕过资产状态机）</li></ul></li></ul><h2 id="业务闭环-e2e-已验证" tabindex="-1">业务闭环（E2E 已验证） <a class="header-anchor" href="#业务闭环-e2e-已验证" aria-label="Permalink to “业务闭环（E2E 已验证）”">​</a></h2><p>创建资产(<code>IDLE</code>) → 投用(<code>IN_USE</code>) → 建维修单(<code>CREATED</code>) → 派工(<code>SCHEDULED</code>) → 维修中(<code>REPAIRING</code>，<strong>联动资产→MAINTENANCE</strong>) → 完成(<code>DONE</code>)；非法跳转（如 <code>IDLE→MAINTENANCE</code>、<code>CREATED→DONE</code>）均被状态机以 <code>ILLEGAL_TRANSITION</code> 拒绝并落库不变。</p><h2 id="工程位置" tabindex="-1">工程位置 <a class="header-anchor" href="#工程位置" aria-label="Permalink to “工程位置”">​</a></h2><p><code>E:/8.cangku/for-job/openbiz-eam-app</code>（含 README 与 E2E 脚本，端口 18086）</p><h2 id="价值" tabindex="-1">价值 <a class="header-anchor" href="#价值" aria-label="Permalink to “价值”">​</a></h2><p>与工单 / MES / PMS / CRM / ERP 共同坐实「百套流水线」可复制：独立工程 + 选定 <code>openbiz-*</code> 构件 + 自建 Mapper / Service，且本例额外验证了「跨实体状态联动」这类复杂业务规则同样可承载。</p><hr><p>上一级：<a href="/my-vitepress-site/apps/openbiz/">OpenBiz 试水实证</a></p>',13)])])}const b=o(i,[["render",n]]);export{_ as __pageData,b as default};
